const bodyLengthFields = ["طول أمام","طول خلف"] as const;
const bodyFields = ["طول أمام","طول خلف","الكتف","مقاس الصدر","مقاس العرض","مقاس عند الجيوب","مقاس الخطوة تحت","الخانة تحت"] as const;
const bodySingleFields = bodyFields.filter(field=>!(bodyLengthFields as readonly string[]).includes(field));
const sleeveBaseFields = ["طول اليد","سعة اليد من فوق","سعة اليد من الوسط","سعة اليد من تحت"] as const;
const sleevePlainFields = ["الخبنة"] as const;
const sleeveCuffFields = ["طول الكبك","عرض الكبك"] as const;
const collarFields = ["محيط الرقبة","مقاس القلاب الأول","مقاس القلاب الثاني","مقاس الرقبة السادة"] as const;
const measurementFields = [...bodyFields,...sleeveBaseFields,...sleevePlainFields,...sleeveCuffFields,...collarFields] as const;
const fabricFields = ["ID القماش","اسم القماش","طول الجنزور"] as const;
const thobeTypes = ["سعودي","قطري","إماراتي","كويتي"] as const;
const defaultCategories = ["نوع الثوب","اليد السادة","الكبك","القلاب","الرقبة السادة","الجيب","السحب","الجنب وأسفل الثوب","التطريز","الأزرار","الجنزور والتخليص"];

function blankFields(fields:readonly string[]){return Object.fromEntries(fields.map(field=>[field,""])) as Record<string,string>}
function blankThobe():ThobeDraft{return {measurements:blankFields(measurementFields),fabric:blankFields(fabricFields),designs:{},thobeType:"سعودي",sleeveMode:"سادة",collarMode:"قلاب",neckButtonCount:"1",neckButtonType:"طقطق",notes:""}}
function cloneThobe(thobe:ThobeDraft):ThobeDraft{return {...thobe,measurements:{...thobe.measurements},fabric:{...thobe.fabric},designs:{...thobe.designs}}}
function databaseDate(value:string){return new Date(value.replace(" ","T"));}
function dayKey(date:Date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`;}
function dateInputValue(date:Date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`;}
function deliveryAfter(days:number){const date=new Date();date.setHours(0,0,0,0);date.setDate(date.getDate()+days);return dateInputValue(date)}
function sequenceNumber(value:string){const digits=String(value??"").replace(/\D/g,"");return digits?digits.replace(/^0+(?=\d)/,""):value}
function normalizedArabic(value:string){return value.trim().toLocaleLowerCase("ar").replace(/[أإآ]/g,"ا").replace(/ى/g,"ي").replace(/ة/g,"ه").replace(/\s+/g," ")}
function comparableThobe(thobe:ThobeDraft){const designs=Object.fromEntries(Object.entries(thobe.designs).filter((entry):entry is [string,DesignOption]=>Boolean(entry[1])).sort(([a],[b])=>a.localeCompare(b)).map(([category,option])=>[category,option.id]));return JSON.stringify({measurements:thobe.measurements,fabric:thobe.fabric,designs,thobeType:thobe.thobeType,sleeveMode:thobe.sleeveMode,collarMode:thobe.collarMode,neckButtonCount:thobe.neckButtonCount,neckButtonType:thobe.neckButtonType,notes:thobe.notes})}
function latinDigits(value:string){return value.replace(/[٠-٩۰-۹]/g,digit=>String("٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹".indexOf(digit)%10));}
function numericValue(value:string){return Number(latinDigits(value).replace(/[^0-9.-]/g,""))||0}
function objectValue(value:unknown):Record<string,unknown>{return value!==null&&typeof value==="object"&&!Array.isArray(value)?value as Record<string,unknown>:{};}
function parseObject(value:string):Record<string,unknown>{try{return objectValue(JSON.parse(value))}catch{return {}}}
function textRecord(value:unknown):Record<string,string>{return Object.fromEntries(Object.entries(objectValue(value)).map(([key,item])=>[key,item===null||item===undefined?"":String(item)]));}
function durationLabel(milliseconds:number){const totalMinutes=Math.max(0,Math.floor(milliseconds/60000));const hours=Math.floor(totalMinutes/60);const minutes=totalMinutes%60;if(hours===0)return `${numberFormat.format(minutes)} دقيقة`;return `${numberFormat.format(hours)} ساعة${minutes?` و ${numberFormat.format(minutes)} دقيقة`:""}`;}
function imageFromFile(file:File){return new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error("read"));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(new Error("image"));image.onload=()=>{const scale=Math.min(1,1200/Math.max(image.width,image.height));const canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext("2d")?.drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL("image/jpeg",.84));};image.src=String(reader.result);};reader.readAsDataURL(file);});}

type IconName = "person"|"search"|"whatsapp"|"finance"|"supplier"|"income"|"delivery"|"notes"|"report"|"access"|"inventory";
const rightMenu:[string,IconName][] = [["إضافة عميل","person"],["بحث عن عميل","search"],["إعلانات واتساب","whatsapp"],["المعاملات المالية","finance"],["الموردون","supplier"]];
const leftMenu:[string,IconName][] = [["دخل إضافي","income"],["توزيع الثياب","delivery"],["ملاحظات جديدة","notes"],["تقرير يومي","report"],["الصلاحيات","access"],["المخزون","inventory"]];
